import{_ as r,l as o,o as e,c as n,v as t,p as l,x as i,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"incast","description":"","frontmatter":{"title":"incast","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/incast.md","filePath":"cs/incast.md","lastUpdated":1789023840000}'),h={name:"cs/incast.md"};function C(u,a,T,_,E,P){const s=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="incast" tabindex="-1">incast <a class="header-anchor" href="#incast" aria-label="Permalink to &quot;incast&quot;">​</a></h1><div class="epigraph"><p>许多发送方同时打向同一接收方的浅缓冲，瞬时队列溢出；丢的是尾，TCP 超时把好链路当成死。 </p><footer>—— 据 Chen, Braud 等数据中心 TCP incast 研究；Alizadeh 等对 DCTCP 动机整理</footer></div><p><a href="/cs/datacenter-clos">上一课</a> 的多对一仍汇到叶子出口。<a href="/cs/output-queue-hol">输出排队</a> 已说热点。缺口是<strong>应用同步扇入</strong>：MapReduce shuffle、存储多块并发读。本课不把 DCTCP 标记写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RTO 最小在毫秒，数据中心 RTT 在微秒。incast：N 个流的初始窗口同时到达，叶子出端口缓冲只有几十到上百 KB，丢包 → 超时 → 吞吐塌成「好网很慢」。不是 \\(C\\) 不够，是瞬态超订。巨帧让一包占更多缓冲。PFC 可避免丢，但暂停波及 Clos 其它流。</p><p>不要把 incast 写成广域拥塞崩溃：时间尺度与扇入结构不同。</p><p><span class="marginnote">文献用 barrier 同步流量复现。本课不给攻击。对策方向：更深缓冲（加重 bufferbloat）、减小 IW、AQM、DCTCP、应用限流。</span></p><h3 id="同步扇入打浅缓冲" tabindex="-1">同步扇入打浅缓冲 <a class="header-anchor" href="#同步扇入打浅缓冲" aria-label="Permalink to &quot;同步扇入打浅缓冲&quot;">​</a></h3><p>不是平均 \\(C\\) 不够。短流凑不够 dupACK 只剩 RTO。ECMP 不拆同一出口。加大缓冲会转向膨胀。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：N 发送 → 一出口浅队列 → 丢 → RTO。对照 HOL：结构内部也可丢；incast 强调应用同步。ECMP 帮不上：目的是同一叶子口。</p>',11)),(e(),l(p,null,{default:i(()=>[d(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22N%20%E4%B8%AA%E5%8F%91%E9%80%81%E6%96%B9%22%5D%20--%3E%20Q%5B%22%E6%B5%85%E5%87%BA%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20DROP%5B%22%E5%B0%BE%E4%B8%A2%22%5D%0A%20%20DROP%20--%3E%20RTO%5B%22%E8%B6%85%E6%97%B6%22%5D%0A%20%20RTO%20--%3E%20THR%5B%22%E5%90%9E%E5%90%90%E5%A1%8C%E9%99%B7%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Clos 过订购比放大汇聚。RoCE 后课更怕丢，故无损。TCP 快速重传要三个 dupACK，短流可能根本凑不够——只剩超时。这把<a href="/cs/tcp-rto">RTO</a> 课的下限暴露成数据中心 bug。</p><p>应用层：限制并发、请求错开，是端到端对策，符合 Saltzer。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每种存储协议的扇入参数。DCTCP 是下一课。后课默认：incast = 同步多对一打浅缓冲。</p><p>加大缓冲能盖 incast，会把延迟交给后课缓冲膨胀。</p><p>上一课留下的缺口在本课收口；「incast」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/dctcp">DCTCP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同步扇入溢出浅队列，RTO 主导。</li><li>ECMP 不拆同一出口。</li><li>对策在 AQM/DCTCP/应用限流，不只加带宽。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：数据中心 incast 文献；DCTCP 动机。</li></ul>',10))])}const A=r(h,[["render",C]]);export{m as __pageData,A as default};
